// 临时验证脚本：断连、在途请求跨 reload、并发 reload
import http from 'node:http';
import net from 'node:net';

const port = Number(process.argv[2]);
const base = { host: '127.0.0.1', port };

let failures = 0;
function check(name, actual, expected) {
  const ok = actual === expected;
  if (!ok) failures += 1;
  console.log(`${ok ? 'PASS' : 'FAIL'} ${name}: got=${JSON.stringify(actual)} expected=${JSON.stringify(expected)}`);
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

function request(method, reqPath, body) {
  return new Promise((resolve, reject) => {
    const data = body ?? '';
    const req = http.request({ ...base, method, path: reqPath, headers: data ? { 'Content-Length': Buffer.byteLength(data) } : {} }, (res) => {
      let chunks = '';
      res.on('data', (c) => (chunks += c));
      res.on('end', () => resolve({ status: res.statusCode, version: res.headers['x-contractlab-version'], body: chunks }));
    });
    req.on('error', reject);
    if (data) req.write(data);
    req.end();
  });
}

function rawSend(bytes, destroyAfterMs) {
  return new Promise((resolve, reject) => {
    const sock = net.connect(port, '127.0.0.1');
    sock.on('connect', () => sock.write(bytes));
    sock.on('error', reject);
    setTimeout(() => {
      sock.destroy();
      resolve();
    }, destroyAfterMs);
  });
}

function reload() {
  return request('POST', '/__contractlab/reload', '');
}

async function main() {
  // 当前为 v3：/api/x [A(delay1200), B]；POST /ab [ab-0 d0, ab-1 d800, ab-2 d0]
  const h0 = await request('GET', '/__contractlab/health');
  check('start version', h0.body, JSON.stringify({ status: 'ok', version: 3 }));

  // 1) 未完整接收即断开 → 不推进序列
  await rawSend('POST /ab HTTP/1.1\r\nHost: x\r\nContent-Length: 100\r\n\r\n01234', 200);
  await sleep(100);

  // 2) 完整 POST → 第 0 项
  const r1 = await request('POST', '/ab', 'ping');
  check('after partial-abort, sequence at item0', r1.body, 'ab-0');

  // 3) 完整 POST 后、延迟结束前断开（预留已成立）→ 仍消费第 1 项
  const sock = net.connect(port, '127.0.0.1');
  await new Promise((res) => sock.on('connect', res));
  sock.write('POST /ab HTTP/1.1\r\nHost: x\r\nContent-Length: 4\r\n\r\nping');
  await sleep(150); // 服务器已完整接收并预留 ab-1（delay 800），此时断开
  sock.destroy();
  await sleep(1000); // 等定时器触发（发送失败被忽略，消费成立）

  // 4) 序列应已到第 2 项
  const r2 = await request('POST', '/ab', 'ping');
  check('reserved-then-disconnect still consumed -> item2', r2.body, 'ab-2');
  const r3 = await request('POST', '/ab', 'ping');
  check('last item reused', r3.body, 'ab-2');

  // 5) 在途请求跨 reload：v3 下预留 A（delay 1200），等待期间换成 v4
  const inflight = request('GET', '/api/x');
  await sleep(300);
  const rl = await reload(); // 外部已把文件改成 v4（/api/x 仅一项 "C-v4"）
  check('reload to v4 ok', rl.body, JSON.stringify({ ok: true, version: 4 }));
  const rf = await inflight;
  check('in-flight uses OLD version body', rf.body, 'A');
  check('in-flight carries OLD version header', rf.version, '3');

  // 6) 新请求使用新版本；旧在途请求不得推进新序列
  const rn = await request('GET', '/api/x');
  check('new request uses v4 item0 (old in-flight did not advance it)', rn.body, 'C-v4');
  check('new request version header', rn.version, '4');
  const rn2 = await request('GET', '/api/x');
  check('v4 single item reused', rn2.body, 'C-v4');

  // 7) 并发 reload 串行化：同文件并发两次，版本应连续 +1 且均成功
  const [c1, c2] = await Promise.all([reload(), reload()]);
  const j1 = JSON.parse(c1.body);
  const j2 = JSON.parse(c2.body);
  check('concurrent reload both ok', JSON.stringify([j1.ok, j2.ok]), '[true,true]');
  check('concurrent reload versions consecutive', JSON.stringify([j1.version, j2.version]), '[5,6]');

  // 8) 旧序列对象在替换后不再被推进（v3 的 /api/x 已消费 A；若错误推进新序列，上面已暴露）
  console.log(failures === 0 ? 'ALL PASS' : `${failures} FAILURES`);
  process.exit(failures === 0 ? 0 : 1);
}

main().catch((e) => { console.error(e); process.exit(1); });

